create schema if not exists tc_cost_private;
revoke all on schema tc_cost_private from public,anon;
grant usage on schema tc_cost_private to authenticated;
create table public.tc_csi_reference_codes(code text primary key check(code ~ '^[0-9]{8}$'),description text not null,division text not null,default_type text not null check(default_type in ('SUB','LAB','MAT','EQUIP','GR','OHP','OTHER')),source_sha256 text not null);
create table public.tc_company_cost_codes(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),code text not null check(code ~ '^[A-Za-z0-9][A-Za-z0-9 ._-]{0,23}$'),description text not null check(length(btrim(description)) between 2 and 250),default_type text not null check(default_type in ('SUB','LAB','MAT','EQUIP','GR','OHP','OTHER')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(company_id,code));
alter table public.tc_csi_reference_codes enable row level security;
alter table public.tc_company_cost_codes enable row level security;
create function tc_cost_private.access_company(cid uuid,write_ boolean default false) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$
 select exists(select 1 from public.profiles where id=auth.uid() and active) and (
 exists(select 1 from public.company_users cu join public.profiles pr on pr.id=cu.user_id where cu.company_id=cid and cu.user_id=auth.uid() and cu.active and pr.role::text in ('admin','executive'))
 or exists(select 1 from public.company_members cm where cm.company_id=cid and cm.user_id=auth.uid() and lower(cm.role) in ('executive','admin','administrator','controller','accounting','accountant','finance'))
 or (not write_ and exists(select 1 from public.projects p where p.company_id=cid and tc_import_private.can_access(p.id,'budget'))));
$$;
create policy cost_reference_read on public.tc_csi_reference_codes for select to authenticated using(exists(select 1 from public.profiles where id=auth.uid() and active));
create policy cost_custom_read on public.tc_company_cost_codes for select to authenticated using(tc_cost_private.access_company(company_id,false));
revoke all on public.tc_csi_reference_codes,public.tc_company_cost_codes from public,anon,authenticated;
grant select on public.tc_csi_reference_codes,public.tc_company_cost_codes to authenticated;
create function tc_cost_private.catalog(cid uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
begin
 if not coalesce(tc_cost_private.access_company(cid,false),false) then raise exception 'Company budget/accounting access required' using errcode='42501';end if;
 return jsonb_build_object('canManage',tc_cost_private.access_company(cid,true),'codes',(select jsonb_agg(x order by x->>'code') from (
 select jsonb_build_object('code',code,'description',description,'division',division,'default_type',default_type,'source','reference') x from public.tc_csi_reference_codes
 union all select jsonb_build_object('code',code,'description',description,'division',left(code,2),'default_type',default_type,'source','custom') from public.tc_company_cost_codes where company_id=cid) q));
end $$;
create function tc_cost_private.add_code(cid uuid,code_ text,description_ text,type_ text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare result_ public.tc_company_cost_codes;
begin
 if not coalesce(tc_cost_private.access_company(cid,true),false) then raise exception 'Company accounting/admin permission required to add codes' using errcode='42501';end if;
 code_:=upper(btrim(code_));description_:=btrim(description_);
 if code_ is null or code_ !~ '^[A-Za-z0-9][A-Za-z0-9 ._-]{0,23}$' or description_ is null or length(description_) not between 2 and 250 or type_ is null or type_ not in ('SUB','LAB','MAT','EQUIP','GR','OHP','OTHER') then raise exception 'Valid code, description and cost type are required' using errcode='22023';end if;
 if exists(select 1 from public.tc_csi_reference_codes where code=code_) then raise exception 'This reference code already exists. Select it from the catalog.' using errcode='23505';end if;
 if result_.id is null then select * into result_ from public.tc_company_cost_codes where company_id=cid and code=code_;if result_.description<>description_ or result_.default_type<>type_ then raise exception 'Code already exists with different details' using errcode='23505';end if;end if;
 return to_jsonb(result_);
end $$;
create function tc_cost_private.valid_code(cid uuid,code_ text) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from public.tc_csi_reference_codes where code=code_) or exists(select 1 from public.tc_company_cost_codes where company_id=cid and code=code_)$$;

-- Manual budget lines coexist with reviewed import lines. Source-derived actuals stay locked.
alter table public.project_budget_lines add column record_version integer not null default 1,add column client_request_id uuid unique,add column creation_payload jsonb,add column created_by uuid references public.profiles(id);
create table public.tc_budget_line_events(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),line_id uuid not null references public.project_budget_lines(id),actor_id uuid not null references public.profiles(id),action text not null,before_data jsonb,after_data jsonb not null,created_at timestamptz not null default now());
alter table public.tc_budget_line_events enable row level security;
alter table public.project_budget_lines enable row level security;
do $$declare r record;begin for r in select policyname from pg_policies where schemaname='public' and tablename='project_budget_lines' loop execute format('drop policy %I on public.project_budget_lines',r.policyname);end loop;end $$;
create policy cost_budget_read on public.project_budget_lines for select to authenticated using(tc_import_private.can_access(project_id,'budget'));
create policy cost_budget_event_read on public.tc_budget_line_events for select to authenticated using(tc_import_private.can_access(project_id,'budget'));
revoke all on public.project_budget_lines,public.tc_budget_line_events from public,anon,authenticated;
grant select on public.project_budget_lines,public.tc_budget_line_events to authenticated;
create function tc_cost_private.budget_add(pid uuid,request_ uuid,data_ jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare cid uuid;r public.project_budget_lines;amount_ numeric;total_ numeric;
begin
 if not coalesce(tc_import_private.can_access(pid,'budget'),false) then raise exception 'Project budget permission required' using errcode='42501';end if;
 select company_id into cid from public.projects where id=pid for update;
 if request_ is null or jsonb_typeof(data_) is distinct from 'object' then raise exception 'Invalid request' using errcode='22023';end if;
 select * into r from public.project_budget_lines where client_request_id=request_;
 if found then if r.project_id<>pid or r.created_by<>auth.uid() or r.creation_payload<>data_ then raise exception 'Request already used' using errcode='40001';end if;return to_jsonb(r);end if;
 if not tc_cost_private.valid_code(cid,data_->>'code') or nullif(btrim(data_->>'scope'),'') is null or length(data_->>'scope')>500 or coalesce(data_->>'costType','') not in ('SUB','LAB','MAT','EQUIP','GR','OHP','OTHER') then raise exception 'Select a catalog code, scope and cost type' using errcode='23514';end if;
 amount_:=(data_->>'budget')::numeric;
 if amount_ is null or amount_::text in ('NaN','Infinity','-Infinity') or amount_<0 or amount_>999999999999 or round(amount_,2)<>amount_ then raise exception 'Budget must be a nonnegative amount to cents' using errcode='23514';end if;
 select coalesce(sum(forecast_cost),0) into total_ from public.project_budget_lines where project_id=pid and active;
 select total_+coalesce(sum((payload->>'totalForecast')::numeric),0) into total_ from public.tc_project_imports where project_id=pid and kind='budget' and status='approved';
 update public.projects set forecast_cost=total_,updated_at=now() where id=pid;
 return to_jsonb(r);
end $$;
create function tc_cost_private.budget_forecast(line_ uuid,expected_ integer,amount_ numeric) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare r public.project_budget_lines;old_ jsonb;pid uuid;total_ numeric;
begin
 select project_id into pid from public.project_budget_lines where id=line_;
 if not coalesce(tc_import_private.can_access(pid,'budget'),false) then raise exception 'Project budget permission required' using errcode='42501';end if;
 perform 1 from public.projects where id=pid for update;
 select * into r from public.project_budget_lines where id=line_ and active for update;
 if not found or r.record_version is distinct from expected_ then raise exception 'Budget line changed. Refresh before editing.' using errcode='40001';end if;
 if amount_ is null or amount_::text in ('NaN','Infinity','-Infinity') or abs(amount_)>999999999999 or round(amount_,2)<>amount_ then raise exception 'Forecast must be a valid amount to cents' using errcode='23514';end if;
 old_:=to_jsonb(r);update public.project_budget_lines set forecast_cost=amount_,projected_variance=current_budget-amount_,record_version=record_version+1,updated_at=now() where id=line_ returning * into r;
 select coalesce(sum(forecast_cost),0) into total_ from public.project_budget_lines where project_id=pid and active;
 select total_+coalesce(sum((payload->>'totalForecast')::numeric),0) into total_ from public.tc_project_imports where project_id=pid and kind='budget' and status='approved';
 update public.projects set forecast_cost=total_,updated_at=now() where id=pid;return to_jsonb(r);
end $$;
-- Keep imported forecast updates from dropping manual budget additions.
do $$declare definition_ text;begin
 definition_:=pg_get_functiondef('tc_import_private.tc_apply_project_import(uuid,integer,jsonb)'::regprocedure);
 if position('set forecast_cost=forecast,' in definition_)=0 then raise exception 'Import implementation changed; review patch';end if;
 execute replace(definition_,'set forecast_cost=forecast,','set forecast_cost=forecast+(select coalesce(sum(forecast_cost),0) from public.project_budget_lines where project_id=pid and active),');
 definition_:=pg_get_functiondef('tc_import_private.tc_update_import_forecast(uuid,integer,integer,numeric)'::regprocedure);
 if position('set forecast_cost=total,' in definition_)=0 then raise exception 'Forecast implementation changed; review patch';end if;
 execute replace(definition_,'set forecast_cost=total,','set forecast_cost=total+(select coalesce(sum(forecast_cost),0) from public.project_budget_lines where project_id=pid and active),');
end $$;

-- Retain cost type and scope on actual journal and charge allocations.
alter table public.tc_accounting_journal_lines add column cost_type text,add column scope_name text;
alter table public.tc_charge_allocations add column cost_type text,add column scope_name text;
create function tc_cost_private.validate_coding() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
begin
 if new.csi_code is not null and not tc_cost_private.valid_code(new.company_id,new.csi_code) then raise exception 'Unknown CSI cost code. Add a company cost code before using it.' using errcode='23514';end if;
 if new.cost_type is not null and new.cost_type not in ('SUB','LAB','MAT','EQUIP','GR','OHP','OTHER') then raise exception 'Invalid cost type' using errcode='23514';end if;
 return new;
end $$;
create trigger cost_journal_coding before insert or update of csi_code,cost_type on public.tc_accounting_journal_lines for each row execute function tc_cost_private.validate_coding();
create trigger cost_charge_coding before insert or update of csi_code,cost_type on public.tc_charge_allocations for each row execute function tc_cost_private.validate_coding();
do $$declare d text;begin
 d:=pg_get_functiondef('public.tc_create_journal_draft(uuid,text,uuid,date,text,jsonb)'::regprocedure);
 if position('csi_code,debit,credit,description)' in d)=0 then raise exception 'Journal implementation changed; review patch';end if;
 d:=replace(d,'csi_code,debit,credit,description)','csi_code,debit,credit,description,cost_type,scope_name)');
 d:=replace(d,$patch$code,dr,cr,item->>'description')$patch$,$patch$code,dr,cr,item->>'description',item->>'cost_type',item->>'scope_name')$patch$);execute d;
end $$;
do $$declare d text;begin
 d:=pg_get_functiondef('public.tc_review_charge_split(uuid,jsonb)'::regprocedure);
 if position('csi_code,amount)' in d)=0 then raise exception 'Charge implementation changed; review patch';end if;
 d:=replace(d,'csi_code,amount)','csi_code,amount,cost_type,scope_name)');
 d:=replace(d,'v_code,v_amount);',E'v_code,v_amount,v_item->>\'cost_type\',v_item->>\'scope_name\');');execute d;
end $$;
revoke all on all functions in schema tc_cost_private from public,anon,authenticated;
grant execute on function tc_cost_private.access_company(uuid,boolean),tc_cost_private.catalog(uuid),tc_cost_private.add_code(uuid,text,text,text),tc_cost_private.budget_add(uuid,uuid,jsonb),tc_cost_private.budget_forecast(uuid,integer,numeric) to authenticated;
create function public.tc_cost_catalog(p_company uuid) returns jsonb language sql security invoker set search_path=pg_catalog,public as $$select tc_cost_private.catalog(p_company)$$;
create function public.tc_cost_add(p_company uuid,p_code text,p_description text,p_type text) returns jsonb language sql security invoker set search_path=pg_catalog,public as $$select tc_cost_private.add_code(p_company,p_code,p_description,p_type)$$;
create function public.tc_budget_add(p_project uuid,p_request uuid,p_data jsonb) returns jsonb language sql security invoker set search_path=pg_catalog,public as $$select tc_cost_private.budget_add(p_project,p_request,p_data)$$;
create function public.tc_budget_forecast(p_line uuid,p_expected integer,p_amount numeric) returns jsonb language sql security invoker set search_path=pg_catalog,public as $$select tc_cost_private.budget_forecast(p_line,p_expected,p_amount)$$;
revoke all on function public.tc_cost_catalog(uuid),public.tc_cost_add(uuid,text,text,text),public.tc_budget_add(uuid,uuid,jsonb),public.tc_budget_forecast(uuid,integer,numeric) from public,anon;
grant execute on function public.tc_cost_catalog(uuid),public.tc_cost_add(uuid,text,text,text),public.tc_budget_add(uuid,uuid,jsonb),public.tc_budget_forecast(uuid,integer,numeric) to authenticated;

